CL = "client_checklist"
TK = "client_checklist_task"


def _s(v):
    return str(v if v is not None else "").strip()


def _link_ids(rec, key):
    out = []
    for v in ((rec or {}).get("links") or {}).get(key) or []:
        if isinstance(v, dict):
            if v.get("id"):
                out.append(str(v["id"]))
        elif v:
            out.append(str(v))
    return out


def _record(slug, rid):
    if not rid:
        return {}
    res = api.records.get(type_slug=slug, record_id=rid) or {}
    return res.get("record") or {}


def _open_item(item_id):
    if not item_id:
        return None
    t = api.workq.get(todo_id=item_id)
    if t and _s(t.get("status")) not in ("done", "cancelled"):
        return t
    return None


rid = _s(params.get("record_id"))
to = _s(params.get("to_stage"))
frm = _s(params.get("from_stage"))
actor = _s(params.get("actor_id"))
practice_manager = _s(params.get("practice_manager"))
outcome = "Nothing to do."

rec = _record(TK, rid)
if rec:
    d = rec.get("data") or {}
    cl_ids = _link_ids(rec, "checklist")
    cl = _record(CL, cl_ids[0]) if cl_ids else {}
    approver = _s((cl.get("data") or {}).get("manager")) or practice_manager
    task = _s(d.get("changed_title")) or _s(rec.get("title"))
    where = _s(cl.get("title")) or "a client checklist"
    reason = _s(d.get("reason"))
    required = bool(d.get("required_task"))
    item_id = _s(d.get("approval_item_id"))

    if to == "removed" and required and frm != "removal_requested" and not (approver and actor == approver):
        # A required task can't skip approval: send it back, which raises the approval item on the next event.
        api.records.change_stage(type_slug=TK, record_id=rid, stage="removal_requested",
                                 note="Required task: removing it needs the checklist manager's approval.")
        outcome = "Sent back for approval: " + task
    elif to == "removed" and required and approver and actor and actor != approver:
        api.records.change_stage(type_slug=TK, record_id=rid, stage="removal_requested",
                                 note="Only the checklist's manager can approve removing a required task.")
        outcome = "Not the approver, so sent back: " + task
    elif to == "removal_requested":
        if not _open_item(item_id):
            link = "/records/" + TK + "/" + rid
            desc = ("**" + task + "** on " + where + "\n\n"
                    + "Reason given: " + (reason or "(none)") + "\n\n"
                    + "Open the task: [" + task + "](" + link + ")\n\n"
                    + "To approve, move the task to **Removed**. To decline, move it back to **Kept**.")
            kw = {"title": "Approve removing a required task: " + task + " (" + where + ")",
                  "description": desc, "priority": "medium", "labels": ["checklist", "approval"]}
            if approver:
                kw["assignee_ids"] = [approver]
            item = api.workq.create(**kw)
            api.records.update(type_slug=TK, record_id=rid, record={"data": {"approval_item_id": _s(item.get("id"))}})
            if approver:
                api.notify.send(title="Approval needed: remove \"" + task + "\"", body=where, user_ids=[approver])
            outcome = "Approval requested: " + task
        else:
            outcome = "Approval already open: " + task
    elif frm == "removal_requested":
        item = _open_item(item_id)
        if item:
            word = "approved: the task is removed" if to == "removed" else "declined: the task stays (" + to + ")"
            api.workq.comment(todo_id=item_id, body="Removal " + word + ".")
            api.workq.complete(todo_id=item_id)
        outcome = "Approval closed: " + task
